    {"id": "c2", "value": -12}
  ],
  "entities": [
    {"id": "axes", "kind": "axes", "role": "coordinate axes"},
    {"id": "xIntercept", "kind": "point", "role": "common x-intercept", "label": "(-3, 0)"},
    {"id": "yIntercept", "kind": "point", "role": "common y-intercept", "label": "(0, 2)"},
    {"id": "commonLine", "kind": "line", "role": "graph of both equations"},
    {"id": "equation1", "kind": "label", "role": "first equation", "label": "-2x + 3y = 6"},
