  ],
  "constructions": [
    {
      "id": "makeAxes",
      "operator": "axes",
      "inputs": {"xMin": -5, "xMax": 4, "yMin": -2, "yMax": 5},
      "outputs": ["axes"]
    },
    {
      "id": "makeXIntercept",
      "operator": "point",
      "inputs": {"x": -3, "y": 0, "coordinateSpace": "world"},
      "outputs": ["xIntercept"]
    },
    {
      "id": "makeYIntercept",
      "operator": "point",
      "inputs": {"x": 0, "y": 2, "coordinateSpace": "world"},
      "outputs": ["yIntercept"]
    },
    {
      "id": "makeCommonLine",
      "operator": "line",
      "inputs": {"start": "xIntercept", "end": "yIntercept"},
      "outputs": ["commonLine"]
    },
    {
      "id": "labelEquation1",
      "operator": "label",
      "inputs": {"target": "commonLine", "text": "-2x + 3y = 6"},
      "outputs": ["equation1"]
    },
    {
      "id": "labelEquation2",
      "operator": "label",
      "inputs": {"target": "commonLine", "text": "4x - 6y = -12"},
      "outputs": ["equation2"]
    }
  ],
  "relations": [],
