{
  "schemaVersion": "scene-document/v2",
  "visualDecision": {
    "mode": "scene",
    "reason": "The two stated equations determine one common line."
  },
  "source": {
    "question": "Explain the graph and number of solutions of -2x + 3y = 6 and 4x - 6y = -12."
  },
  "quantities": [
    {"id": "a1", "value": -2},
    {"id": "b1", "value": 3},
    {"id": "c1", "value": 6},
    {"id": "a2", "value": 4},
    {"id": "b2", "value": -6},
    {"id": "c2", "value": -12}
  ],
  "entities": [
    {"id": "ax", "kind": "axes", "role": "coordinate axes"},
    {"id": "eq1", "kind": "label", "role": "first given equation", "label": "-2x + 3y = 6"},
    {"id": "eq2", "kind": "label", "role": "second given equation", "label": "4x - 6y = -12"},
    {"id": "common", "kind": "polyline", "role": "graph of both equations"}
  ],
  "constructions": [
    {"id": "makeAxes", "operator": "axes", "inputs": {"xMin": -5, "xMax": 5, "yMin": -2, "yMax": 5}, "outputs": ["ax"]},
    {"id": "showEq1", "operator": "label", "inputs": {"target": "ax", "text": "-2x + 3y = 6"}, "outputs": ["eq1"]},
    {"id": "showEq2", "operator": "label", "inputs": {"target": "ax", "text": "4x - 6y = -12"}, "outputs": ["eq2"]},
    {"id": "plotCommon", "operator": "function_curve", "inputs": {"expression": "(2/3)*x + 2", "variable": "x", "xMin": -5, "xMax": 4}, "outputs": ["common"]}
  ],
  "relations": [],
  "assertions": [
    {"id": "yIntercept", "predicate": "function_value", "entities": ["common"], "expected": {"x": 0, "y": 2}, "severity": "fatal"},
    {"id": "xIntercept", "predicate": "root", "entities": ["common"], "expected": -3, "severity": "fatal"}
  ],
  "annotations": [
    {"id": "equivalence", "kind": "narration", "targetIds": ["eq1", "eq2"], "text": "Multiplying the first equation by −2 gives the second, so their graphs coincide."},
    {"id": "solutions", "kind": "narration", "targetIds": ["common"], "text": "Every point on the common line satisfies both equations. The solution set is {(x, (2/3)x + 2) : x is any real number}, so there are infinitely many solutions."}
  ],
  "requiredEntityIds": ["ax", "eq1", "eq2", "common"],
  "revealGroups": [
    {"id": "setup", "entityIds": ["ax", "eq1", "eq2"], "dependsOn": []},
    {"id": "graph", "entityIds": ["common"], "dependsOn": ["setup"]}
  ],
  "teachingTimeline": []
}
